draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // potato
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // underground
  ctx.fillStyle = '#964B00';
  ctx.fillRect(W/2 - 100, H/2 + 50, 200, 100);

  // starch energy
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 70 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2 - 50, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 - 30);
  ctx.lineTo(W/2 - 70, H/2); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 - 10);
  ctx.lineTo(W/2 - 50, H/2 + 20); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 - 10);
  ctx.lineTo(W/2 - 90, H/2 + 20); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2);
  ctx.lineTo(W/2 - 70, H/2 + 50); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2);
  ctx.lineTo(W/2 - 50, H/2 + 50); // leg
  ctx.stroke();

  ctx.restore();
}
